{
  "probability": 0.98,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "Anchor the forecast to the IOM Missing Migrants Project's Central Mediterranean deaths counts as the reference class for channeling the likelihood.",
    "Current mortality pace (~606 deaths/missing by February 2026) provides a strong upward signal that, if sustained into March–April, would exceed 1,000 before May 2026.",
    "Historical baselines (2024–2025) show high mortality on Mediterranean routes, supporting plausibility of crossing the 1,000-death threshold within the timeframe.",
    "Calibrated updates include seasonal/wave conditions and potential protective factors (SAR capacity, deterrence) that could temper the pace, but data gaps could push totals higher; overall, the estimate remains highly likely."
  ],
  "confidence": "high",
  "narrative": "Early-2026 mortality pace and historical patterns imply a high likelihood of reaching at least 1,000 Mediterranean deaths before May 2026. The posterior probability is 0.98, with a calibrated uncertainty range roughly 0.90–0.99, acknowledging data gaps and potential shifts in rescue capacity and policy responses.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Using IOM Missing Migrants Project annual counts for the Central Mediterranean as the reference class; this anchor probability reflects a modest initial starting point before applying updates, given the strong early-year signal but known uncertainties."
    },
    "factor_updates": [
      {
        "factor": "Current mortality pace (as of February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "As of February 2026, about 606 deaths/missing; if this pace persists into March–April, total deaths could exceed 1,000 before May 2026."
      },
      {
        "factor": "Seasonal/weather conditions into late winter/early spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Rough seas and winter storms are associated with higher fatalities; persistent adverse conditions into spring could sustain a high death toll."
      },
      {
        "factor": "Historical high toll baseline (2024–2025) indicating persistent high mortality",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past years saw 2,452 (2024) and 1,328 (2025) deaths, suggesting a high baseline risk that makes 1,000 deaths plausible."
      },
      {
        "factor": "Search-and-rescue capacity and policy responses reducing fatalities",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "SAR presence and policies can rescue more people and lower fatalities; however budget cuts could offset some gains."
      },
      {
        "factor": "Policy/deterrence and interdiction efforts reducing crossing volume",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence and interdiction may suppress crossing attempts, lowering death counts, unless flows shift to more dangerous routes."
      },
      {
        "factor": "Underreporting and data gaps in IOM Missing Migrants Project",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Counts may undercount fatalities; improvements in reporting could reveal higher totals, nudging probability upward."
      }
    ],
    "synthesis_rationale": "The final probability is anchored by a central-immediate pace signal (606 by Feb 2026) and strong historical baselines that suggest 1,000 by May is plausible (up factors). Mitigating factors such as SAR capacity and deterrence provide countervailing pulls, while data gaps could push actual totals higher; overall, the updates were weighted toward a high-likelihood outcome, with calibration reflecting potential correlations among factors and inherent uncertainty."
  }
}

